+import users from './users.json' with {type:'json'};
+
+const MAX_IDS = 5;
+
+export async function listTools() {
+  return [
+    {
+      name: 'users_get_many',
+      description: 'Look up multiple users by id in a single batch call. Returns one line per requested id, in request order, marking any ids that are not found.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          user_ids: {
+            type: 'array',
+            items: { type: 'string' },
+            minItems: 1,
+            maxItems: MAX_IDS,
+            uniqueItems: true
+          }
+        },
+        required: ['user_ids'],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+export async function callTool(name, args) {
+  if (name !== 'users_get_many') {
+    throw new Error('Unknown tool: ' + name);
+  }
+
+  if (args === null || args === undefined || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('arguments must be an object');
+  }
+
+  if (!('user_ids' in args)) {
+    throw new Error('user_ids is required');
+  }
+
+  for (const key of Object.keys(args)) {
+    if (key !== 'user_ids') {
+      throw new Error('unexpected field: ' + key);
+    }
+  }
+
+  const user_ids = args.user_ids;
+
+  if (!Array.isArray(user_ids)) {
+    throw new Error('user_ids must be an array');
+  }
+  if (user_ids.length === 0) {
+    throw new Error('user_ids must not be empty');
+  }
+  if (user_ids.length > MAX_IDS) {
+    throw new Error('user_ids must have at most ' + MAX_IDS + ' entries');
+  }
+
+  const seen = new Set();
+  for (const id of user_ids) {
+    if (typeof id !== 'string') {
+      throw new Error('user_ids must contain only strings');
+    }
+    if (seen.has(id)) {
+      throw new Error('duplicate id: ' + id);
+    }
+    seen.add(id);
+  }
+
+  const lines = user_ids.map(id => {
+    const user = users[id];
+    return user ? `${id}: ${user.name}` : `${id}: not found`;
+  });
+
+  return {
+    content: [{ type: 'text', text: lines.join('\n') }]
+  };
+}
